   else{$pdo->prepare('INSERT INTO bdc_judge_profile_requests(full_name,display_name,country,city,photo_url,instagram,email,phone,whatsapp,preferred_contact,dance_styles,judge_role,qualified_divisions,qualified_rounds,languages,biography,experience,certification) VALUES(:name,:display,:country,:city,:photo,:instagram,:email,:phone,:whatsapp,:preferred,:styles,:role,:divisions,:rounds,:languages,:bio,:experience,:certification)')->execute($d);$success='Your judge profile was submitted for organiser approval.';$_POST=[];}
