?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BDC Judge Profile</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="<?=e(url('public/assets/css/app.css'))?>" rel="stylesheet"><style>.crop{width:min(240px,100%);aspect-ratio:4/5;overflow:hidden;background:#e5e7eb;border:1px solid #d6dce5;border-radius:18px;position:relative;touch-action:none;user-select:none}.crop img{position:absolute;max-width:none;pointer-events:none}.tools{padding:14px;border:1px solid #dfe5ec;border-radius:14px;background:#f8fafc}</style></head><body class="bg-light"><main class="container py-4 py-md-5" style="max-width:980px"><h1 class="h2 mb-1"><?=$updating?'Update Your Judge Profile':'BDC Judge Profile'?></h1><p class="text-muted mb-4"><?=$updating?'Secure access expires '.e((string)$judge['profile_link_expires_at']).'. Save every change from this page.':'Submit your judging profile for organiser approval.'?></p><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($token!==''&&!$judge):?></main></body></html><?php exit;endif;?><form method="post" enctype="multipart/form-data" class="card border-0 shadow-sm"><div class="card-body p-3 p-md-4"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="profile_token" value="<?=e($token)?>"><input type="hidden" name="cropped_photo_data" id="cropData"><div class="d-none"><input name="website" tabindex="-1"></div><div class="row g-4"><div class="col-md-4"><div class="crop mx-auto" id="frame"><img id="photo" src="<?=e($photoSrc)?>" crossorigin="anonymous" draggable="false"></div><label class="form-label mt-3">Judge photo</label><input class="form-control" id="photoInput" type="file" name="photo" accept="image/jpeg,image/png,image/webp"><div class="form-text">JPG, PNG or WebP, maximum 5 MB.</div><div class="tools mt-3"><label class="form-label">Zoom and position</label><input class="form-range" id="zoom" type="range" min="1" max="3" step=".01" value="1"><div class="form-text">Drag the photo inside the frame.</div></div><?php if($updating&&!empty($judge['photo_url'])):?><label class="form-check mt-3"><input class="form-check-input" type="checkbox" name="remove_photo"> Remove current photo</label><?php endif;?></div><div class="col-md-8"><div class="row g-3"><?php foreach(['full_name'=>'Full name *','display_name'=>'Display name','country'=>'Country','city'=>'City','instagram'=>'Instagram','languages'=>'Languages'] as $k=>$label):?><div class="col-md-6"><label class="form-label"><?=$label?></label><input class="form-control" name="<?=$k?>" value="<?=e($val($k))?>"<?=$k==='full_name'?' required':''?>></div><?php endforeach;?></div></div></div><hr><h2 class="h5">Private contact details</h2><div class="row g-3"><?php foreach(['email'=>'Email','phone'=>'Phone','whatsapp'=>'WhatsApp'] as $k=>$label):?><div class="col-md-4"><label class="form-label"><?=$label?></label><input class="form-control"<?=$k==='email'?' type="email"':''?> name="<?=$k?>" value="<?=e($val($k))?>"></div><?php endforeach;?><div class="col-md-6"><label class="form-label">Preferred contact</label><select class="form-select" name="preferred_contact"><?php foreach(['none'=>'No preference','email'=>'Email','whatsapp'=>'WhatsApp','either'=>'Either'] as $v=>$label):?><option value="<?=$v?>"<?=$sel('preferred_contact',$v)?>><?=$label?></option><?php endforeach;?></select></div></div><hr><h2 class="h5">Judging qualifications</h2><div class="row g-3"><div class="col-md-6"><label class="form-label d-block">Dance styles</label><?php foreach($styles as $v=>$label):?><label class="form-check form-check-inline"><input class="form-check-input" type="checkbox" name="dance_styles[]" value="<?=$v?>"<?=$has('dance_styles',$v)?' checked':''?>> <?=$label?>