=document.getElementById('zoom'),out=document.getElementById('cropData');let x=0,y=0,drag=false,pid,sx,sy,dirty=false;const current=<?=$updating&&!empty($judge['photo_url'])?'true':'false'?>;function draw(){if(!img.naturalWidth)return;const w=frame.clientWidth,h=frame.clientHeight,s=Math.max(w/img.naturalWidth,h/img.naturalHeight)*Number(zoom.value),iw=img.naturalWidth*s,ih=img.naturalHeight*s,mx=Math.max(0,(iw-w)/2),my=Math.max(0,(ih-h)/2);x=Math.max(-mx,Math.min(mx,x));y=Math.max(-my,Math.min(my,y));Object.assign(img.style,{width:iw+'px',height:ih+'px',left:(w-iw)/2+x+'px',top:(h-ih)/2+y+'px'})}img.onload=draw;window.onresize=draw;zoom.oninput=()=>{dirty=true;draw()};file.onchange=()=>{if(file.files[0]){x=y=0;zoom.value=1;dirty=true;img.src=URL.createObjectURL(file.files[0])}};frame.onpointerdown=e=>{drag=true;dirty=true;pid=e.pointerId;sx=e.clientX-x;sy=e.clientY-y;frame.setPointerCapture?.(pid)};frame.onpointermove=e=>{if(drag&&e.pointerId===pid){x=e.clientX-sx;y=e.clientY-sy;draw()}};['pointerup','pointercancel'].forEach(t=>frame.addEventListener(t,()=>drag=false));form.onsubmit=()=>{if((!dirty&&!file.files.length)||(!current&&!file.files.length))return;const c=document.createElement('canvas');c.width=640;c.height=800;const ctx=c.getContext('2d'),r=img.getBoundingClientRect(),f=frame.getBoundingClientRect(),sx=640/f.width,sy=800/f.height;ctx.drawImage(img,(r.left-f.left)*sx,(r.top-f.top)*sy,r.width*sx,r.height*sy);out.value=c.toDataURL('image/jpeg',.9)};draw()})();</script></body></html>
